import java.util.*;

public class Main {
    static List<List<Integer>> verticalTraversal(TreeNode root) {
        List<int[]> items = new ArrayList<>();                     // each: {col, row, val}
        dfs(root, 0, 0, items);
        items.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
        List<List<Integer>> result = new ArrayList<>();
        int curCol = Integer.MIN_VALUE;
        for (int[] item : items) {
            if (item[0] != curCol) { result.add(new ArrayList<>()); curCol = item[0]; }
            result.get(result.size() - 1).add(item[2]);
        }
        return result;
    }

    static void dfs(TreeNode node, int row, int col, List<int[]> items) {
        if (node == null) return;
        items.add(new int[]{col, row, node.val});
        dfs(node.left, row + 1, col - 1, items);
        dfs(node.right, row + 1, col + 1, items);
    }
}

