vector<vector<int>> verticalTraversal(TreeNode* root) {
    vector<array<int,3>> items;                                    // each: {col, row, val}
    function<void(TreeNode*,int,int)> dfs = [&](TreeNode* node, int row, int col) {
        if (!node) return;
        items.push_back({col, row, node->val});
        dfs(node->left, row + 1, col - 1);
        dfs(node->right, row + 1, col + 1);
    };
    dfs(root, 0, 0);
    sort(items.begin(), items.end());                                  // sorts by (col,row,val) via array ordering
    vector<vector<int>> result;
    int curCol = INT_MIN;
    for (auto& item : items) {
        if (item[0] != curCol) { result.push_back({}); curCol = item[0]; }
        result.back().push_back(item[2]);
    }
    return result;
}
